#!/usr/bin/env node
import fs from 'fs';
import path from 'path';
import { fileURLToPath } from 'url';

const dir = path.join(path.dirname(fileURLToPath(import.meta.url)), '_chunks-120');

const pitcheiTeshuva = {
  "1#_": "Eating vessels. Chochmas Adam wrote general rule 73 law 13: the large cauldrons in which they brew beer — it appears to me they require tevilat kelim; and even though they fix them and attach them to the ground, nevertheless their law is like a vessel and they have no remedy except that one immerse them or pierce in them a large hole that nullifies them from the category of vessel, and afterward a Jewish craftsman repairs them. But according to what I heard, that the beer they brew in them is not fit for drinking at all until they filter it, it is possible that on this basis the world relies that they do not immerse them; nevertheless requires study, for they are no worse than a slaughter knife below seif 5, since it is fit to use for another food — see in his book Binas Adam more on this:",
  "2#_": "Glass. See She'eilat Yaavetz vol. 1 siman 67, who wrote that vessels coming from overseas countries called porcelain and similar to glass vessels do not require tevilah, since it is known that their making is from sand and earth, and metal vessels are spoken of in the parashah; and even though they are thinner, we have no concern for this, for glass vessels are thinner than they, and if not for the fact that when they break they can be repaired by melting — for this reason they equated them to metal vessels — they would require tevilah, and these do not have that remedy — see there:",
  "3#_": "To immerse them. Chochmas Adam wrote there law 15: one must insert the entire vessel in water at one time so that none of it remains outside the water, even any amount; and if it is large and one cannot immerse it all at once, it appears to me it is forbidden to immerse in halves, similar to immersion of a niddah, and it is not comparable to hag'alah, which is to expel the prohibition — and once he hag'alah part, he has expelled — but here it is because of impurity, and since part of it remains outside the water, impurity returns and spreads through the entire vessel — end of his words:",
  "4#_": "In a mikveh or in water. Chochmas Adam wrote there law 19: it appears to me that in a time of pressing need it is permitted to immerse a glass vessel in snow if it is in one place (see below siman 201 seif 30), for its tevilah is certainly d'rabbanan; but not metal vessels, for according to many poskim it is d'oraisa — see there. [And see responsum Machzik Bracha siman 43 s.v. the general principle that emerges, who wrote that he found in Maharil that he testified before his teachers that they forbade immersing vessels in a well because when they clean them it becomes invalid as drawn water, etc. — see there; and see below siman 201 seif 40 in the gloss and what he wrote there s.k. 28]:",
  "5#_": "That the vessel be loose. Shach — what he challenged on this (and it is brought in Baer Heitev s.k. 3) — and it appears his view is that here too in tevilat kelim, even though he loosened his hands, the tevilah did not take effect, a decree lest he not loosen; and see Tiferes Moshe, who resolved his difficulty in Turei Zahav, that there regarding tevilah of impurity a decree is appropriate, for if he does not loosen he may come to a severe prohibition with his hands, such as that he may have relations with a niddah or place in a pure terumah vessel and eat it and it carries the death penalty; which is not so here, for even if he uses this vessel afterward he does not eat a prohibition, for what is inside is not forbidden, as Rama wrote at the end of this siman — therefore they did not decree on this — end of his words — see there:",
  "6#_": "That it does not require tevilah. See responsum Shev Yaakov siman 31 regarding vessels fixed in an oven from which they take hot water for kneading dough — he inclined to say they do not require tevilah at all, even if they are of metal, and even though sometimes they pour hot tea-water from them; nevertheless we follow the majority of its use — see there:",
  "7#_": "The matzah irons. Baer Heitev in the name of Taz and Shach. And see Peri Megadim Orach Chaim siman 491 in Mishbetzot s.k. 26, who wrote in Yiddish that they place matzos on them — even according to Shach tevilah is required (without a blessing), for it is fit for actual food use. And he further wrote: rib eizen that a non-Jew made requires tevilah with a blessing, for they separate bread with it and call out; and rib eizen that a Jew bought from a non-Jew and pierced it requires study — see there further:",
  "8#_": "Pepper mill. See She'eilat Yaavetz vol. 8 end of seif 7, who wrote that mills with which they grind light beans from which they make the beverage kave — it appears they are liable for tevilah, for they are preferable to a pepper mill — see there. And it appears that for this tevilah is without a blessing, since cooking is required — see Baer Heitev s.k. 6; and likewise Peri Megadim Orach Chaim siman 491 in Mishbetzot s.k. 26 — see there:",
  "9#_": "To cut cards. Baer Heitev; and see Binas Adam, gate Issur VeHeter siman 65 regarding what they practice at large feasts, to borrow coated earthenware vessels and glass vessels from a Jewish shopkeeper; and he wrote that even though Taz and Shach are concerned for the view of Issur VeHeter to immerse without a blessing when the first bought for cards or commerce, nevertheless since Rama did not bring the view of Issur VeHeter at all, and Peri Chadash also disagrees with him — if so, for Shabbat or guests or a large feast where there is concern they may break if immersed and there will be loss, or there is no time, one may rely to use without tevilah, for tevilat kelim of these is only d'rabbanan according to all; and it is possible that Issur VeHeter also did not write thus except regarding metal vessels, for according to many poskim tevilah is d'oraisa, and so one should be stringent with metal vessels, for it is a doubt of d'oraisa — see there. And see responsum Chinuch ben Yomo siman 52, who wrote on this: a Jew who borrows a glass vessel from a Jewish shopkeeper and agrees with him that he will pay him the value of breakages during the meal and the remainder returns to him if he pays for breakages only according to the seller's principal and gives him a fixed sum for the loan — he is considered a renter, and his law is like the law of a borrower who does not require tevilah (and according to Taz one should immerse it without a blessing); but if he pays breakages according to what he profits on it, he is considered a purchase, for borrowing appraises how much it is worth in the market for any person, and therefore he must immerse — see there; and it appears he means with a blessing:",
  "10#_": "If he bought it. See responsum Radvaz vol. 2 siman 945, what he wrote on this:",
  "11#_": "He immerses it. Peri Chadash wrote: it is reasonable that glass vessels, for which one is not liable to immerse them except d'rabbanan, are a doubt of d'rabbanan and to be lenient; and whoever does not see in the non-Jew's mind that he wishes to sink them does not require tevilah — see there:",
  "12#_": "To immerse it without a blessing. Chochmas Adam wrote: it appears to me that a Jew who holds a glass factory where they make glass and has gentile workers, or the reverse, may rely on those who are lenient, and in time of need it is permitted to use without tevilah, for it is a doubt of d'rabbanan. And shopkeepers must warn buyers of glass not to bless on the immersion unless he holds a gentile glass factory and gentile workers — see there:",
  "13#_": "Requires tevilah. And accordingly, when he sells cauldrons to a non-Jew orally because of chametz that requires tevilah after Pesach, and therefore it is better not to sell them — Chochmas Adam there law 3. And it is clear to me that I saw thus in responsum Shivat Tzion in the name of his father the gaon, may his memory be blessed, in the order of selling chametz:",
  "14#_": "We do not believe a minor. Because tevilat kelim is d'oraisa — Taz; and see Peri Megadim Orach Chaim siman 491 in Mishbetzot s.k. 26, who wrote requires study, that even with glass vessels, which are d'rabbanan, it also appears he is not believed, since he has a presumption of prohibition like siman 127 seif 3 at the end of the gloss. However, with glass, whoever reached thirteen years need not check after bar mitzvah; and with metal vessels one may say he must know he is an adult — end of his words; however one may say that here too with metal vessels one need not know, for here it is lighter than every d'oraisa prohibition, since if he transgressed and used without tevilah what is inside is not forbidden, as Rama wrote at the end of this siman, and as I wrote this reasoning above s.k. 5 in the name of Tiferes Moshe — see there; and see above siman 201 s.k. 7 and investigate:",
  "15#_": "And afterward he borrows it from him. See responsum Rashbash siman 468, who hesitated about this leniency, for it is like an evasion and forbidden — see there; and see responsum Sha'agat Aryeh siman 56 and siman 57, who raised that during bein hashemashot of erev Shabbat and erev Yom Tov one does not immerse metal vessels that require tevilah d'oraisa, but glass vessels, which are d'rabbanan, are permitted; but on Shabbat and Yom Tov themselves, even glass vessels one does not immerse, because this tevilah is not for today's need but for weekday need, and it is forbidden — see there:",
};

const tureiZahav = {
  "1#א": "Eating vessels. For it is written: every item that comes into fire; and there is no way to use fire except for needs of eating. Of metal, for it is written: only the gold, etc., and all mentioned in the verse is called metal. Glass too has the law of metal, since if it breaks it can be repaired by melting. And the reason for tevilah is so that they emerge from the impurity of the non-Jew to the sanctity of Israel:",
  "1#ב": "Or a spring of forty se'ah. Beit Yosef challenged what Tur wrote — it is not clear, etc., for regarding impurity too he ruled in siman 201 that we require forty se'ah; and Darkei Moshe resolved that Tur challenges according to the view of Sefer HaMitzvos, who wrote: even though a spring, etc. (end of his words), that according to him it suffices with less than forty se'ah for impurity, but he is stringent in this tevilah over that — our rabbi wondered why the difference. And it is not pleasing to me from Tur's wording, also from the law, for certainly Semak too holds that for a woman it does not suffice in a spring less than forty se'ah, but for an impure vessel it suffices with ten. And it appears to me the explanation of Tur's words is thus: this tevilah of vessels of a non-Jew we derive in the last chapter of Avodah Zarah from what is said \"and it shall be pure\"; and in truth there is no implication of \"and it shall be pure\" that it be through water — let us say through something else. Also what they said there that we derive from \"only in the waters of a niddah\" — there is no resolution in this, for the plain meaning of the verse refers to waters of sin-offering, as Rashi explained in the Chumash; rather we must interpret this \"and it shall be pure,\" which is through water, since it is written regarding impure vessels \"in water it shall be brought and it shall be pure\" — from this we learn: in what do we find that this \"and it shall be pure\" regarding vessels of a non-Jew also refers to water? And after it is clarified that \"and it shall be pure\" refers to water, we interpret \"waters of a niddah\" as waters in which a niddah immerses, and it teaches us that it does not suffice with less than forty se'ah like a niddah, as stated in the Gemara. And in Tur we read \"more than tevilah of impurity,\" and he means impure vessels; and this is what he says: since we do not know that purification is in water for vessels of a non-Jew except from tevilah of impure vessels, we do not be more stringent than them regarding a spring, except in what the Torah revealed regarding a mikveh, that it should be like a niddah:",
  "1#ג": "He immerses without a blessing. For the coating inside is only for ornament:",
  "2#_": "And specifically if he moistened his hand in mikveh water, etc. The rabbi left room here to defend himself, for his honor is in its place — he did not analyze this gloss at all, although they follow Mordechai at the end of Avodah Zarah, as we will quote shortly in the name of Darkei Moshe; nevertheless one must understand Mordechai's words and explain them as we will set forth, with God's help. First we will mention the essence of this matter that Tur and Shulchan Aruch mentioned — that rinsing one's hand in water helps — and this is what we teach in the mishnah, chapter 8 of Mikvaot: one who holds a person and vessels and immerses them — they are impure; and if he rinsed his hands in pure water, R. Shimon says he should loosen his hands so water enters them. And Rashi explained: he rinsed his hand before holding — pure, because moisture on his hand connects to mikveh water and there is no chatzitzah here. And likewise Tur brought in siman 197, and likewise at the end of Tur HaAroch. This is according to what we teach in chapter 6 of Mikvaot: one draws and moistens even a hair's breadth — meaning there one wishes to purify invalid water from valid mikveh water, and by moistening them a hair's breadth all invalid water is purified; and this halachah is widespread that moisture of a fingerbreadth to moisten helps to connect to a valid mikveh, as stated in chapter 2 of Gittin (daf 16). This is the intent of the mishnah we mentioned, that one who holds a person or vessel should rinse his hands in water — meaning before holding the vessel he should moisten his hands, even in detached water, and through their connection to the mikveh the water on his hand becomes actual mikveh water through hashakah; therefore the tanna and later poskim used the language of rinsing generally, like all rinsings that are in detached water — not like Rama, who explained Tur's words specifically in mikveh water; rather detached water also helps through hashakah. And what Darkei Moshe wrote in the name of Mordechai at the end of Avodah Zarah, that specifically mikveh water is required — this is Mordechai's language there: he also taught that one should be careful to immerse a glass vessel full of water and place it in a bucket full of water and sink the bucket in a pit, not to set it on its rim lest the weight of the vessel be a chatzitzah, but tilt it on its side and roll it in the bucket in the pit; and one asked: what is different from a person's foot spread on the ground in a mikveh, where there is no chatzitzah, because we say the water precedes the place before he puts his foot on the ground, as we teach in chapter 7 of Mikvaot: they immersed a bed in it even though its legs sink in thick mud — valid, because the water precedes. One might say: only in a complete mikveh where they are attached; but when one puts glass in a bucket, even full of water, it does not help because they are detached; and one should also be careful from what we teach in chapter 8 of Mikvaot: one who holds a person and vessels, etc. — end of Mordechai. From this Rama learned to explain here that the rinsing Tur mentioned is in mikveh water. In truth this is another matter: Mordechai deals with the weight of the vessel that interrupts the mikveh when it lies, and it is not applicable to say the water under the vessel is purified by hashakah from mikveh water unless there were already valid mikveh water under the vessel; then even though the vessel's weight interrupts so one might say those waters were completely cut off from the mikveh, nevertheless they remained connected and have connection on every side to remain in their validity — unlike detached water in a vessel, which you must purify through hashakah and create purity from the outset; for this a good connection is required, and since the vessel has weight it is not called a good connection. But in truth one who immerses a vessel in his hand in a mikveh does not need mikveh water on the hand; since there is no weight of a vessel, hashakah to detached water already on his hand with mikveh water is fine; nevertheless the person immersing must not grip the vessel forcefully, for then it is like the vessel's weight we mentioned — rather moderate contact, as they said regarding a niddah immersing in several places regarding her eyes and lips. This is Mordechai's intent: he also wrote one should be careful from what the mishnah says, one who holds, etc. — he asked: does the mishnah come to inform us? Rather it teaches that one must be careful not to grip too forcefully; for although the first tanna argues with R. Shimon, who holds he must loosen his hands, nevertheless moderate contact is required even for the first tanna, not with force — this is simple. And I saw in Mishmeres HaBayis of Rashba daf 190: we rule like the first tanna that he need not loosen his hands, only that he rinsed his hands first and does not press hard — tevilah is valid. And it appears to me Tur holds that if he grips moderately in his hand it is permitted even l'chatchila, and we do not decree lest he grip with great force and mikveh water connection not help; and this is why he wrote \"however if he moistened, etc.,\" there is no concern — he asked: why \"there is no concern\" — he should have said permitted or it is fine; rather it teaches there is no concern lest he grip too hard. And Rosh is even more lenient, for he does not hold the vessel's weight interrupts and nullifies the connection of detached water on his hands with mikveh water; for he wrote in Hilchot Mikvaot: because the water precedes and touched the bed's legs before touching mud, and those waters are connected to the mikveh — therefore there is no chatzitzah, as we teach in chapter 8 of Mikvaot; and for this reason one need not lift his legs during immersion because the water precedes — end of Rosh. Behold he equated this law to rinsing hands, where the rinse-water is detached; nevertheless since Mordechai distinguishes between vessel weight or not, one should be stringent; therefore one who wishes to immerse a vessel should moisten his hands even in detached water, hold the vessel with moderate contact, and immerse it. One who wishes to immerse a vessel full of detached water in a bucket should draw water from the mikveh and place it with the vessel in water; then he must turn it on its side, for this is like a person gripping a vessel forcefully and immersing it — the person holding is voluntary and can hold without great force, unlike a full heavy vessel — unless the bucket is sunk in water and he lowers the vessel into it; then we are not concerned for vessel weight, since there is already valid water inside, as we said. And Levush writes that inside the water he passes it hand to hand; although that is a good method, for in that way there is no prohibition even if he grips hard, as Issur VeHeter wrote at the end of general rule 58 law 96 — nevertheless this is not the mishnah's method, which stated generally that he rinses his hands in water first; and Tur and Shulchan Aruch are not explained at all in that method, but in the method we said — and even detached water suffices, since there is no vessel weight and no gripping with force, tevilah is proper even l'chatchila; and even according to Mordechai we mentioned, who holds vessel weight is a chatzitzah, even if hands were moistened first in detached water, there is no concern here at all lest he grip with force, for it is a fixed halachah that we are not concerned for this even for niddah impurity, as will be explained in siman 198 seif 28, with Heaven's help:",
  "3#_": "He blesses on tevilat kelim. Darkei Moshe wrote in the name of Mordechai, chapter HaSho'el: some require blessing on tevilah of metal vessels so it not imply other vessels not liable for tevilah — end of his words; and likewise in Hagahot Ashiri — end of his words. I wondered: if so, he should also bless on metal eating vessels so it not imply vessels not for eating; rather one need not mention in the blessing all details of the mitzvos' explanations. And it is not comparable to Chanukah candle blessing of \"ner\" without specifying Chanukah, for there the essence of the mitzvah is Chanukah, as here with vessels; and covering blood with earth — we wrote the reason in its place that he blesses on two coverings. Therefore it appears to my humble opinion one should not change the custom at all; and afterward I found greater still at the end of Issur VeHeter in a responsum, and this is its language: but Mahariz Ronkel answered one should not mention \"vessel,\" only immerse plainly:",
  "4#_": "Tripod. In foreign tongue \"dreifus\"; but fidleash means trivet in foreign tongue:",
  "5#_": "Slaughter knife. Mordechai wrote the reason it is not considered an eating vessel: it is forbidden to cut with it even cold; and although the animal is fit for eating, nevertheless it still requires cooking — end of his words. And likewise the skinning knife is not used to eat with as it is now — likewise Issur VeHeter. And it appears since Rama wrote on this \"and good to immerse without a blessing,\" the same applies to iron implements for matzah that he wrote afterward do not require tevilah — likewise immerse without blessing, for one reason applies to both; only Rama wrote it here because Issur VeHeter wrote it in a gloss on this, and Tur listed scissors among vessels without eating needs — from the Talmud at the end of Avodah Zarah, where R. Ashi asked: even wool shears too? Rashi explained: scissors with which they shear wool garments; and the Gemara answers: eating vessels the Torah spoke of. And Perishah wrote Tur's scissors means even what they trim vegetables with. Maharshal disagreed and wrote he was not precise, for vegetable scissors are eating vessels, for in Choshen Mishpat siman 97 it lists tools for making food — end of his words. I say Perishah is correct, for at the end of chapter HaMekabel they say a butcher's resting-knife is for food needs, and Rashi explains it is butchers' knife for cutting meat — and see the skinning knife is also butchers' knife and does not require tevilah for the reason we mentioned; rather certainly \"tool for making food\" does not apply to eating vessels at all. The questioner who asked from wool shears could have asked from vegetables, but he preferred to ask; and furthermore Choshen Mishpat there lists slaughter knife, and here Mordechai and Shulchan Aruch ruled no tevilah is needed — Perishah's words are true. And Issur VeHeter wrote: likewise iron with which they fix kreplekh on Purim or scrape dough in the kneading trough — only if they remove burnt matter from bread when taking it from the oven requires tevilah — end of his words; and in all of them the reason is whatever the user needs cooking for does not require tevilah:",
  "6#_": "Wooden vessel that has, etc. Hoops in foreign tongue \"reifen\"; and Tur wrote in this law it does not require tevilah even for one who follows the stabilizer — meaning R. Meir in the first chapter of Shabbat: glass vessels that were pierced and lead was dripped in — R. Meir defiles because we follow the stabilizer, meaning the lead stabilizes the vessel for use — it is as if all lead; on this he said even R. Meir agrees here we do not say as if all metal, since use is not through that side:",
  "7#_": "Requires tevilah. Tur likewise wrote in the name of Sefer HaMitzvos and concluded: since one uses the silver inside, but not outside, even though it stabilizes; and some are stringent to immerse without a blessing. Beit Yosef explained his second way, which is primary in his view: a silver cup standing on a wooden vessel that surrounds and attaches it requires tevilah, as we say regarding a wooden vessel with iron hoops outside — but not outside, meaning if silver is outside and wood inside, even though silver stabilizes the wood like the wooden vessel with iron hoops that does not require tevilah; and \"some are stringent\" applies to both, whether silver outside stabilizing wood or the reverse, for we are uncertain whether we follow the stabilizer — such is his explanation. And to my humble opinion it is astonishing if Tur explained Semak thus, for then he should have ruled the same for iron hoops above, for Beit Yosef has one law for them — and he contradicts himself within the same breath, for he ruled immediately below iron hoops do not require tevilah even for one who follows the stabilizer; therefore it appears Tur explained Semak regarding vessel within vessel, as Semak explicitly states: silver vessel inside wooden vessel, where the outer is seen somewhat inside too; therefore there is a stabilizer like R. Meir in Shabbat chapter 1 above; only Semak holds we do not follow the outer stabilizer but the essence of use, which is a complete vessel only partly seen as outer inside; on this he said some are stringent when the outer is silver and fully stabilizes to immerse it, but one need not be stringent and bless; but in the first case where the inner is silver and use is essentially silver, certainly tevilah with blessing is required, for whatever is used inside — the stabilizer cannot nullify and exempt from tevilah; and in our Semak it explicitly writes \"some are stringent to immerse where it stabilizes without blessing\" — from this it applies only to this case; and so it appears from Shulchan Aruch here, who first wrote iron hoops do not require tevilah and then wrote silver vessel here requires tevilah — implying even with blessing; he retracted from Beit Yosef and holds \"some are stringent\" applies only to silver outside, as I explained; and Maharshal likewise; and not as Levush wrote that this tevilah Shulchan Aruch mentioned in seif 7 without blessing — rather it requires tevilah with blessing; this is clear. And not only that, but even in Tur's latter case where the outer is silver, since it stabilizes, tevilah with blessing is required, as Rama wrote in seif 10 \"and if part of the silver,\" as I wrote there following those who go after the stabilizer — so here too; but for practical halachah I wrote in seif 10 one should not bless, neither here with outer silver nor there with part of the silver:",
  "8#_": "To cut cards. Beit Yosef wrote: likewise if he bought for commerce it does not require tevilah; Hagahot Ashiri concludes: since it is borrowed in his hand, Beit Yosef learned if he bought it requires tevilah, as Rama wrote shortly; but Issur VeHeter general rule 28 law 87 wrote: since if the first Jew wanted to use it for a meal, even temporarily, he would have had to immerse it — he is thereby obligated — therefore the second Jew borrowing from him must immerse it. I wonder greatly at Rama for not bringing this, neither in Darkei Moshe nor here; and one must say he immerses without a blessing; and likewise one who borrows vessels from a Jewish shopkeeper for a meal immerses without a blessing, only the shopkeeper should inform the buyer afterward not to immerse again with a blessing — as appears to my humble opinion:",
  "9#_": "And if not. In the Gemara we say: Mar bar Rav Ashi said: Father pledged a silver chair from a non-Jew, immersed it, and drank from it; and we do not know whether because he holds a pledge is like a sale, or because it appears the non-Jew intends to sink it; therefore poskim ruled: if we clearly see he intends to sink it, tevilah is required; and if it were not a doubt, it implies even if certainly he does not intend to sink it, there is doubt whether tevilah is required from pledge-as-sale; only Tur wrote: if one does not know whether he intends to sink it, we are in doubt, etc. — implying if certainly he does not intend to sink it, certainly no tevilah. And Beit Yosef writes: where he does not intend to sink it, we are in doubt, etc. — such is primary; and it appears Tur teaches a leniency that even whenever it is not known for certain that he intends to sink it, no tevilah is required, and all the more so when certainly he does not intend; and that he did not teach the reverse leniency that even when he does not intend to sink one may immerse without blessing — this is only a general stringency. And Maharshal wrote: when he does not intend to sink it, a Jew is forbidden to use it because of deceiving the non-Jew; he brought proof from Maharil's laws of Pesach, who wrote it is not proper to use any non-Jewish vessel before it is secured in Jewish hands unless permitted — therefore Tur did not permit here without intent to sink. I say: if there were prohibition of deceit, certainly intent to sink would not help, as pledge-as-sale — for with a Jew's pledge these things certainly do not help; and if there is prohibition with non-Jews, it would be like a Jew — why did Rav Ashi use a non-Jew's pledge without permission from pledge-as-sale? Also Tur and other poskim did not speak of one who transgresses; perhaps Maharil explained Rav Ashi used it with permission — then the question returns: why did Tur not write where certainly he does not intend to sink, for even when unknown there is prohibition from deceit per this view. Nevertheless it appears clear to my humble opinion there is clear permission to use a non-Jew's pledge without permission — it is no worse than canceling his loan in Choshen Mishpat siman 248, which was permitted [meaning in their days, since gentiles then practiced canceling Jewish loans, and Jews measured them as they measured them]. In Bava Kama (daf 113) Rashi explained this is not actual theft, for there is no desecration of God's name, for the non-Jew does not know explicitly that he lies, etc.; and what we say in chapter HaNezikin, Rav Kahana said \"peace unto you, master\" — Rashi: when he gives peace to a non-Jew he does not intend to bless him but his master (God). Tosafot wrote: requires study whether it is permitted because of deceit; likewise in Pe'ah; and above end of siman 117, forbidden to sell him nevelah as if kosher — that is not comparable here, for there he utters falsehood to deceive and receive good reputation or waive money for this lie, like theft from his purse — forbidden with non-Jews as with Jews; unlike here, where even if he could act justly and keep it all for himself there is no prohibition, since it is already in his hand permissibly for the loan; and see further siman 292 seif 2 regarding deceit of non-Jews if it is passive, as the non-Jew said. And I saw in great communities on Sukkot they use painted garments from non-Jewish pledges to decorate the sukkah and lend to many others, and likewise covers — Heaven forbid to say they all transgress; and in truth Maharil himself did not sign on this, only the copyist perhaps heard and erred — as appears to my humble opinion:",
  "10#א": "A Jew who gave silver, etc. Rama brought \"and some disagree\" — these are two views in Tur and Beit Yosef; Beit Yosef strained to explain, as he testified, that he explained everything follows the stabilizer, meaning the non-Jew stabilized the vessel — this is not \"follow the stabilizer\" in Gemara or poskim; and Maharshal explained Ritzba means the non-Jew gives silver needed for repair and disagrees with the law emerging from the first view, not the law itself; from this he wrote Rama was imprecise here — all this does not matter to me. What appears clear: this dispute is itself what Semag's gloss author disputed with Semag — Semag wrote the reason: the non-Jew's name is not called upon it, as Tur wrote; the gloss author wrote: it appears he means even if it did not hold a revi'it before; and Tosafot explained in Avodah Zarah because the vessel's essence is not the non-Jew's; therefore when it did not hold a revi'it before, the vessel's essence is the gentile craftsman for those who say we follow the stabilizer; and Ritzba explicitly wrote tevilah is required where it did not hold a revi'it — end of his words. Tur's intent is also thus: this is obvious if the non-Jew gives silver for the whole vessel — tevilah is required; if he gives a little in a way that stabilizes the vessel, this depends on the dispute of following the stabilizer, as Tur explained above in Sefer HaMitzvos; here he only comes to explain the dispute according to those who say a craftsman acquires through enhancement of the vessel, as Tur ruled in several places in Tur. The first view holds exemption when a non-Jew repairs depends on the reason the non-Jew's name is not called upon it — we require \"his name is called upon it,\" as the mishnah's law; therefore no difference whether it held or not — even without holding a revi'it before repair, the non-Jew's name is not called after repair; and Tur teaches a leniency: if a Jew gave a non-Jew to repair a broken vessel and gives silver to repair, the non-Jew acquires enhancement of the vessel, that repair being slight — obviously no tevilah, for his name is not upon it. But even if a Jew gave silver to a non-Jew to make a new vessel with great enhancement and the gentile craftsman acquired it — one might have said tevilah is required; he teaches: since his name is not upon it, no tevilah. Ritzba disagrees and holds: since the gentile craftsman acquires through enhancement, whether he made a new vessel from Jewish silver with great enhancement, obviously tevilah is required; but even if the non-Jew has only a small repair, he acquires that enhancement and tevilah is required, since that small amount stabilizes — it is as if he gave silver for repair from his own, since he acquired it, and the vessel's essence becomes his — tevilah is required, as Semag's gloss author we mentioned; and we do not care whether the non-Jew's name is called upon it or not. This is a broad explanation with Heaven's help, without stumbling from all Beit Yosef's challenges; and Rama well ruled to immerse without blessing a vessel a Jew gave silver for, etc.; and that he did not bring even giving a broken vessel not holding a revi'it that Ritzba mentioned — because Rama did not decide like him, and perhaps this is included in making a vessel that Shulchan Aruch mentioned, that whatever does not hold a revi'it is not a vessel. And Maharshal wrote in vain that he was imprecise — rather he was precise. And what he wrote \"and if part of the silver,\" this is from Mordechai chapter HaSho'el, brought by Beit Yosef: however if pierced below a revi'it and did not hold because of the hole, and he placed a piece of metal, tevilah is required, for we establish everything follows the stabilizer — end; and Beit Yosef and Darkei Moshe explain it means the non-Jew gave the metal piece from his own — such are Rama's words here in this case only; and according to Ritzba we mentioned, the law is so even from the Jew's own, since he acquires enhancement and stabilizes; only Mordechai does not hold thus, therefore he required metal from the non-Jew. I wonder: Mordechai's words are regarding a broken Jewish vessel that did not hold a revi'it — when the non-Jew places his piece, he causes the vessel's essence; but when making a new vessel from Jewish silver and the non-Jew gives a little from his own, who says that little comes where it stabilizes? Rather say it is nullified in the majority of Jewish silver and is like all the Jew's, for everywhere we follow the majority — therefore this tevilah without blessing is meant; and so Rama's wording implies afterward \"and likewise a Jewish craftsman,\" etc., immerse without blessing; and it is further proved Mordechai tied this ruling to what he ruled everything follows the stabilizer, and we already explained Tur in Sefer HaMitzvos concludes that because of what stabilizes one immerses without blessing — how can we say Rama ruled like those who follow the stabilizer to bless? Rather it is clear: since it is a dispute, one does not bless because of stabilizing, per \"some are stringent\" in Tur I brought above seif 7; therefore tevilah without blessing is required for outer silver above and here for part of the silver that stabilizes:",
  "10#ב": "He immerses it too without a blessing. Question: Issur VeHeter general rule 58 law 94 wrote: a non-Jew who gives silver to a Jew to repair a vessel for him, and the Jew buys it from him — even before it reaches the non-Jew's hand requires tevilah — end; implying even with blessing. And Rama's reason appears: Issur VeHeter's main reason obligating tevilah here is we do not say in this case \"craftsman acquires through enhancement,\" as written there before — only regarding enhancement we say so, not the vessel itself, for the craftsman may not keep it; therefore the craftsman's name is not upon it; and since Rama saw other poskim hold \"craftsman acquires through enhancement\" as Ritzba we mentioned, he ruled here immerse without blessing. But what Rama wrote afterward \"or he gave part of the metals from his own, no tevilah\" — on what does this apply? If relying on \"Jew makes for himself,\" obviously even if the non-Jew gave all metals he said first no tevilah; if on the previous \"craftsman makes for non-Jew,\" it is difficult: since we are concerned perhaps here \"craftsman acquires through enhancement,\" it becomes the non-Jew's vessel — what help that the Jewish craftsman gives part of the silver, since most of the vessel is the non-Jew's? This resembles buying a vessel from a non-Jew with a hole and a Jew repairs with Jewish silver — does that exempt non-Jew obligation? Now we hold the non-Jew's name is upon it — a fortiori from Rama shortly: if part of the silver from which the vessel was made is the non-Jew's, tevilah is required because we follow the stabilizer who is the non-Jew, even though most is the Jew's — all the more so if most is the non-Jew's and minority the Jew's. And further, even a stabilizer name is not here, for he makes a new vessel and is already nullified in the non-Jew's majority, as we mentioned — whence do we uproot tevilah obligation entirely? And even if you explain the non-Jew gives only part, it is still difficult: why above is tevilah required without blessing and here tevilah obligation is uprooted entirely? Therefore it appears there is a scribal error here, and this \"or he gave part of the silver\" belongs earlier; but if, etc., and it teaches two matters: first, if the non-Jew gave all metals, nevertheless he does not bless; and if he gave only part from his own, nevertheless tevilah is required. And so it appears primary to include this law in \"requires tevilah without blessing,\" and there is no obstacle:",
  "11#א": "And he redeemed it — no tevilah. Maharshal wrote: even if he despaired of redeeming; but if initially he pledged with intent not to redeem and changed his mind and redeemed, tevilah is required — end of his words; and although above there is doubt regarding a Jew with a pledge from a non-Jew, here it is different, with proof from chapter Kol Sha'ah (Pesachim daf 31): there is a dispute whether a Jew acquires a pledge from a non-Jew; but a non-Jew from a Jew — all agree he does not acquire:",
  "11#ב": "A Jew whom they stole, etc. — no tevilah. Since he is not permitted to hold it publicly, the non-Jew's name is not called upon it; and even though this one despaired of it — likewise Issur VeHeter in the gloss:",
  "14#_": "We do not believe a minor, etc. Because tevilat kelim is d'oraisa; and if he immersed before an adult, tevilah is valid — Tur wrote the reason in Terumat HaDeshen: even for Rosh who holds a niddah immersing requires intent, nevertheless here an adult can teach the minor to intend to purify; and further, in this tevilah that is not from impurity to purity, who says intent is required? — end; and since Rama did not write here that the adult must teach him, it implies he adopts the latter answer that here intent is not required at all:",
  "15#_": "Their tevilah was valid. At first glance the wording implies b'dieved only, but in truth not so, for in the source of this law — responsum to Ramban — it is written: you asked whether to immerse vessels through a non-Jew — I have not heard this, but it appears permitted, for we do not say intent is required except for washing hands for eating, which is because of terumah concern — end; implying even l'chatchila permitted. That responsum is Rashba's; and in that responsum above he wrote regarding washing hands intent is required, or the washer's or giver's intent — nevertheless he was lenient for tevilat kelim even l'chatchila. And Maharshal wrote Rashba was lenient per his view that a niddah who immersed without intent — but for us who are stringent with niddah, we should be stringent with tevilah by a non-Jew; and through distraction in the text he did not look at siman 198 in Beit Yosef, where Rashba holds niddah requires intent; and behold Rashba is stringent even for washing hands for eating, yet lenient for tevilat kelim — all the more so more lenient than niddah. But I wonder how he can bless on what the non-Jew immerses while the Jew does nothing — therefore it is not proper l'chatchila; and therefore Shulchan Aruch wrote b'dieved language here; but if the Jew also immerses some vessel at that time while the non-Jew helps immerse other vessels, the blessing refers to what the Jew does — it is fine; and this is the responsum to Ramban we mentioned. So appears to my humble opinion:",
  "16#_": "He gives it to a non-Jew as a gift, etc. It appears to me this remedy is only temporary — for that Shabbat, or on a weekday while he has no mikveh; but after Shabbat or when a mikveh becomes available, since it is permanently settled in Jewish hands, it is certainly like purchased in his hand and no better than a non-Jew's pledge in a Jew's hand with intent to sink — tevilah is required. And furthermore regarding a borrowed tallit we find it is exempt from tzitzit for thirty days and afterward obligated, for it appears his own — so here too it appears tevilah is required after he can immerse, even with blessing; but since this is not explicit in poskim, one should be careful to immerse another vessel with it because of concern for a doubtful blessing:",
};

const sifteiKohen = {
  "1#א": "[\"Or of glass or vessels coated with lead, etc. Thus it should read, and that is earthenware vessels and similar coated with lead:\"]",
  "1#ב": "[\"Coated with lead. And Issur VeHeter wrote general rule 58 law 89: vessels coated with glass have the same law as coated with lead:\"]",
  "1#ג": "[\"Some say, etc. Thus it should read, and he argues with the first reason:\"]",
  "1#ד": "[\"He immerses without a blessing. Mordechai wrote in the name of Rama that even if coated only outside with lead, one immerses it without a blessing; Beit Yosef and Darkei Moshe bring it; and Bach wrote one should wonder at the world's custom who use pots coated with lead inside without any immersion at all:\"]",
  "1#ה": "[\"Without a blessing. And it appears one should immerse them with some other vessel with a blessing, as below seif 9; and so it is in Issur VeHeter general rule 58 — see there:\"]",
  "2#א": "[\"Loose in his hand, etc. Requires study, for Beit Yosef and the later authorities did not bring any dispute on this; and Rambam chapter 2 of Hilchot Mikvaot law 11 wrote: one who holds a person and vessels and immerses them — they remain in their impurity, and even if he loosened his hands it is a decree lest he not loosen — end of his words; and Rav Yerocham brings it in his conclusion; and likewise Rashba at the end of Terumat HaDeshen in the name of Rambam; and likewise Rosh in Bava Kama there; and Bach ruled below siman 198 seif 20 regarding immersion of a person that even if loose his tevilah did not take effect; and at the end of chapter 8 of Mikvaot we plainly teach a person and vessels together — see there; requires study:\"]",
  "2#ב": "[\"But not in detached water. See Lechem Chamudot end of Niddah daf 315a what he challenged on this; and one may say that here, if not for the water, it would be a chatzitzah; therefore the water comes to remove from the category of chatzitzah; therefore we require mikveh water — investigate:\"]",
  "3#_": "He blesses on tevilat kelim. And some poskim bless on tevilah of metal vessels; and likewise Bach that this is essential and that he saw them act according to the elders; and likewise Issur VeHeter general rule 98 law 100:",
  "4#_": "But fidleash requires tevilah. Because they roast upon it the food itself — such is Semak's language, meaning what they call in foreign tongue \"roist\":",
  "5#א": "[\"That it does not require tevilah. The reason is explained there: they are not eating vessels, for although the animal is fit for eating, for this reason it is not considered an eating vessel, for it still requires cooking or roasting — end of his words:\"]",
  "5#ב": "[\"The irons, etc. Question: in Issur VeHeter general rule 58 law 2 he compared the irons to a slaughter knife used for skinning that does not require tevilah, since the thing being fixed still requires another repair; if so, since the rabbi wrote regarding a slaughter knife one should immerse without a blessing, the same applies to the irons; and it appears the rabbi holds the irons are even more inferior, for it is impossible to use them for another food, unlike a slaughter knife that can be used for other food; and likewise in Issur VeHeter's gloss there, needles with which fowl are sewn are not judged like a slaughter knife, and a skinning knife since it cannot be used for other food — end; and accordingly what Bach wrote in seif 4 that vegetable scissors are food needs, as regarding injury it is called things with which one makes food for the soul in Choshen Mishpat siman 97 — end of his words — is not clear, for it cannot be used for other food; rather it appears as Perishah wrote that vegetable scissors do not require tevilah; and one may say regarding injury that there even things not food needs they return his plowing tools, adzes, and planes, and likewise slaughter knife — Tur wrote there in seif 8 it is food for the soul, and here he wrote no tevilah is required; accordingly all the more so the awl with which they pierce barrel hoops does not require tevilah, unlike Maharil at the end of Hilchot Tevilah who wrote they require tevilah — and so is the practice:\"]",
  "6#_": "It does not require tevilah. Requires study, for Beit Yosef ruled the halachah that one should immerse it without a blessing, for we are uncertain whether we follow the one who stabilizes it or not; Darkei Moshe brings it in his conclusion; and likewise at the end of Maharil's laws of tevilah one immerses without a blessing; and likewise Issur VeHeter general rule 58 law 49 that one immerses them without a blessing or with other vessels:",
  "7#א": "[\"Requires tevilah, etc. It implies a blessing is required; and even though Beit Yosef ruled regarding a silver cup whose stabilizer is wood that one immerses without a blessing, one may say that there, if not for the wood the cup would not be fit at all and the wood stabilizes it; but here the case is where the cup is fit as is and is only attached to a wooden vessel:\"]",
  "7#ב": "[\"Mill, etc. And Darkei Moshe wrote in the name of Hagahot Maimoniyot that the lower part receiving the spice does not require tevilah; and likewise Issur VeHeter there law 85 that the lower receiving the grindings does not require it, for it is all wood:\"]",
  "7#ג": "[\"And likewise iron funnels, etc. But a wooden funnel with an iron tube does not require tevilah even though one uses it via the iron, since it does not stabilize relative to the funnel; and likewise all similar cases — likewise Issur VeHeter there law 84:\"]",
  "8#א": "[\"Must immerse it. And Issur VeHeter there law 86 ruled tevilah is required; and it appears one should immerse without a blessing or immerse another vessel with it:\"]",
  "8#ב": "[\"Forbidden to use for meal needs. But for non-meal needs it is permitted to use even though he took it for a meal; when he changed his mind to cut cards with it, it does not require tevilah — so Issur VeHeter wrote there law 80:\"]",
  "8#ג": "[\"The second too requires tevilah. Even though the first took it to cut cards and the like:\"]",
  "9#א": "[\"And if not, etc. Meaning he does not know whether the non-Jew intends to sink it in his possession or not; but if he knows clearly the non-Jew does not intend to sink it, it is obvious no tevilah is required — all this I proved in my book from Tosafot and Tur and Maharil's laws of Pesach, who wrote a pledge requires tevilah only when decided in Jewish hands; and in responsum siman 60 he wrote we are in doubt in the Gemara and uncertain, and tevilah is required out of doubt — unlike Bach — see there; however in any case where the non-Jew does not intend to sink it, Maharil wrote one may not use it without the non-Jew's permission because of deceit, forbidden even regarding a non-Jew's property; we do not practice thus, etc.; and it appears he holds there is no deceit of the non-Jew in using it:\"]",
  "9#ב": "[\"And if in the end it sank, etc. Thus it should read. And Issur VeHeter wrote there law 88; nevertheless, if he added money to the non-Jew and bought the pledge from him after they immersed it out of doubt, he requires tevilah again with a blessing, for they did not immerse initially with this intent — end of his words:\"]",
  "10#א": "[\"And some disagree, etc. Bach challenged the rabbi on this and his words are not plausible, as I wrote in my book; the essential law is as Beit Yosef and the rabbi wrote — Tur's view in the name of Ritzba: even with Jewish silver, since the non-Jew makes the main vessel, tevilah is required, whether the non-Jew makes an entirely new vessel or it was pierced and did not hold a revi'it, since the non-Jew stabilizes it — according to Ritzba even Jewish silver; and Maharshal concludes in chapter HaGozel Eitzim siman 22; and we do not explain Ritzba's words only with non-Jew's silver — rather Ritzba disagrees and always holds tevilah is required, for a craftsman acquires through enhancement of the vessel, etc.; and although for halachah Maharshal concludes there no tevilah is required, nevertheless one should certainly be stringent regarding a d'oraisa prohibition; and perhaps even Maharshal only means no tevilah is required by law, therefore one should not bless on it; and so it appears from his language that he wrote therefore, etc., no tevilah is required, and one who immerses with a blessing — the court would rule on him because of a blessing in vain — end of his words:\"]",
  "10#ב": "[\"Requires tevilah. And a blessing:\"]",
  "10#ג": "[\"He immerses it too without a blessing. Because we are uncertain whether we follow the craftsman — and here tevilah is not required — or we follow the one whose silver it is:\"]",
  "10#ד": "[\"Or he gave, etc. Meaning the non-Jew gave the Jew part of the metals from his own and the Jew made it for himself — no tevilah; and it deals where part of the vessel is still the non-Jew's because of his metals; if so it resembles a Jew and non-Jew who received a vessel in partnership — tevilah is required for the reason Issur VeHeter wrote at the end of law 88: for he certainly does not emerge from the name of impurity through this tevilah, for partnership of the non-Jew is still upon it — end; and likewise Taz; and if so the same here; or it appears this is what the rabbi meant: and likewise a Jewish craftsman who made a vessel for a non-Jew, etc., if the non-Jew gave all the metals and he bought it from him — tevilah without blessing; but if he made it for himself only buying metals from the non-Jew, or even made it for the non-Jew and the non-Jew did not give all metals but gave part from his own and afterward bought it — no tevilah; and it appears to the rabbi that Mordechai certainly did not mean where there is part non-Jewish silver tevilah is required only because the non-Jew made it, but when the Jew made it — even according to those who follow whose silver it is, it is possible where part of the silver is the Jew's that he agrees no tevilah is required; and this is the main explanation:\"]",
  "11#א": "[\"But if he pledged it, etc. Even if he intended to sink it in the non-Jew's possession — no tevilah — likewise Issur VeHeter there law 88; and likewise Bach and Perishah in the name of Maharshal, who wrote in his name: if initially he pledged with intent not to redeem and changed his mind and redeemed — tevilah is required:\"]",
  "11#ב": "[\"In partnership — no tevilah. I already wrote the reason in s.k. 22; and from that reason it implies while part of the vessel is still the non-Jew's; but if the Jew returned and bought the non-Jew's share — tevilah is required:\"]",
  "11#ג": "[\"A Jew whom they stole, etc.; but a minister, etc. Taz wrote the reason: a minister or governor who certainly despaired of them — it is as if they sank in non-Jewish hands, etc.; therefore if theft and robbery are in a matter we heard he despaired of them, tevilah is required; and it is not clear, for in Issur VeHeter from which the rabbi brought this law (general rule 58 law 89 on the gloss) he wrote the reason: for a thief and robber, even though they despaired completely, since they are not permitted to hold it publicly, the non-Jew's name is not called upon it and no tevilah is required; Darkei Moshe brings it; and perhaps Taz also agrees to this, only he comes to say that even a minister or governor does not require tevilah except because presumably he despaired and it is as if sunk in non-Jewish hands; but if he did not despair — tevilah is required:\"]",
  "15#_": "Their tevilah was valid. Bach wrote the main reason of Rashba is because he ruled like Rav in chapter 2 of Chullin (daf 31) that a niddah who immersed without intent — her tevilah was valid; but for us who rule below end of siman 198 like R. Yochanan that a niddah requires intent — likewise here their tevilah was not valid — end of his words; and it is difficult, for Rashba ruled like R. Yochanan regarding niddah and Beit Yosef brings it end of siman 198; rather Rashba's main reason is that tevilah here is different, as he brought in this siman his words that he distinguishes; and likewise Terumat HaDeshen siman 257: even those who require intent for niddah — who says this tevilah of vessels, which is not impurity to purity and does not forbid what entered before tevilah and is only a decree of Scripture — requires intent? — end; and so the rabbi's view appears, who ruled plainly here like the Mechaber (and below end of siman 198 regarding niddah he ruled another tevilah is required); and Darkei Moshe ruled plainly like the Mechaber; and further, since he did not write in seif 14 regarding a minor that the adult must teach him to intend to purify, as Darkei Moshe brought in the name of Terumat HaDeshen — evidently he holds like Terumat HaDeshen's conclusion there that for tevilah here intent is not required; and wherever intent is not required, one need not teach him at all, as proven in Tosafot chapter 1 of Chullin daf 12 beginning; and Taz also distinguishes between niddah tevilah and tevilah here — see there; and therefore if vessels fell into water before tevilah, no tevilah is required, as Maharam's responsum — unlike Bach who rejected his words from what he holds intent is required, for this was already explained to be incorrect:",
  "16#_": "He gives it to a non-Jew, etc. See Orach Chaim siman 323 seif 7 — the rabbi wrote another remedy; and see responsum Maharal ibn Chaviv siman 16. Supplement to the laws of tevilat kelim — see below simanim 201 and 202:",
};

const beurHagra = {
  "1#א": "Lead. Rashi and Tosafot there 33b and Ketubot 107b and see above siman 135 seif 6 and Orach Chaim siman 491 s.k. 23:",
  "1#ב": "Inside. So Tosafot explain there s.v. and the halachah and Shulchan Aruch, and like kunya in chapter 2 (33b) there and chapter kli sheni that it is inside — for if outside the earthenware inside absorbs; and likewise in chapter Avodah Zarah (47b) the rim of kunya, etc.:",
  "1#ג": "In a mikveh of, etc. There:",
  "1#ד": "Or a spring, etc. Meaning: even though a spring purifies in a kli sheni, as written in Torat Kohanim \"these were stated\" and \"a gathering of water shall be pure\" — one might think even if he filled water on his shoulder and made a mikveh, l'chatchila it would be pure; Scripture teaches: a spring — just as a spring is by Heaven's hand, so a mikveh by Heaven's hand; if from a spring a spring purifies in a kli sheni, perhaps a mikveh purifies in a kli sheni? Scripture teaches: however — a spring, a spring purifies in a kli sheni, and a mikveh in forty se'ah; and in the first chapter of Mikvaot mishnah 7 and for a spring, etc.; and there chapter 5 mishnah 1 that the spring, etc.; and mishnah 3 and for a spring, etc.; and likewise Rambam and Raavad; but R. Yitzchak explained: only for vessels that are d'oraisa, even in a mikveh a revi'it suffices, as written in the first chapter of Pesachim (17b), even though they nullified revi'it of a mikveh as written in chapter 6 of Nazir (38a) — the spring remains on Torah law and d'rabbanan is discussed there; and even though they expound a verse in Torat Kohanim, it is a rabbinic support; but a person, even in a spring from the Torah requires forty se'ah, from what is written in chapter 3 of Chagigah (22a), for the ground trembles, etc.; and this applies only to a spring where earth roots connect in water under the ground (and see above siman 201 s.k. 6). And Semak wrote: this is for impurity; but here even in a spring we require forty se'ah, as written \"waters in which a niddah immerses,\" etc.; this is his language there: if it wrote \"and it shall be pure,\" etc. — that is in a spring or revi'it of a mikveh d'oraisa, for \"and it shall be pure\" is in what was purified from impurity; and this is Tosafot there s.v. waters even in two; and the same applies to a spring, for they are equal d'oraisa:",
  "1#ה": "Some say, etc. Semak and as Ran explains: only when coated inside and outside; but otherwise one immerses without a blessing:",
  "2#א": "Requires, etc. and if, etc. As written in chapter 8 of Mikvaot: one who holds, etc., and the first tanna; and Rashba explains the first tanna agrees with R. Shimon, only R. Shimon argues with the first tanna that rinsing does not help — unlike Rambam there and in his composition the first tanna argues with R. Shimon and decreed lest he not loosen; for if so, in rings (in Tosefta) chapter 6 of Mikvaot — loose are chatzitzot, not loose are not chatzitzot; and chapter 5 of Shabbat (92b) and they immerse in their place while perforated; and chapter 6 (57a) until he loosens them; and chapter 4 of Yevamot (46a) he loosened them — why do we not decree?",
  "2#ב": "And only, etc. See above siman 202 seif 6 in the gloss: be careful, etc.; and likewise, etc.; and Mordechai likewise at the end of Avodah Zarah: when one places glass full of water in a bucket full of water and sinks in a pit, etc.; and as written in chapter 3 of Chagigah (21a) that the vessel's weight is a chatzitzah; he challenged there from what is written in chapter 7 of Mikvaot: he immersed a bed in it, etc.; and he resolved: here the water in the bucket is detached, therefore it does not help; and he wrote: one should also be careful from what is written there, one who holds, etc., as above; and this is why he wrote \"and only,\" etc.; and the rabbi's words require study, for even when moistening in mikveh water they become detached on the hand; and Mordechai's words are thus: there mikveh water preceded under the bed, unlike here where detached preceded and through pouring into the mikveh it purifies, as Rosh wrote there and below siman 198 paragraph 25; and if so they must be loose so mikveh water will reach them, therefore it does not help; and likewise here the place of the vessel he holds must be in mikveh water first and afterward he holds there; but the mishnah's language \"and if he rinsed his hand,\" etc., does not imply thus; and one must say for his words that there he deals with that he is not pressing and holding with force, only he need not loosen — all this is forced, for the mishnah states plainly; and Mordechai's main law requires study — whence do we distinguish between detached and attached; and chapter 3 of Chagigah where there is no water at all in the outer vessel — and the essence is there is no distinction, as the mishnah states here \"and if he rinsed\" — detached they are, as above; and likewise in the gloss in siman 202 there he did not mention water in the outer vessel; and even with force it helps from what sinks, as above, and as written in siman 198 seif 31:",
  "3#א": "He blesses, etc. As written in Tosefta last chapter of Berakhot: one who performs all mitzvos must bless, etc.; and as written in the Gemara in several places: all mitzvos one blesses, etc.; and in the first chapter of Pesachim (7b):",
  "3#ב": "And if they, etc. In Tosefta there: an individual who performed ten mitzvos blesses on each one; one who performed a mitzvah all day blesses only once; and in the chapter of covering blood 6b:",
  "4#_": "Tripod, etc.; but, etc. As written there: eating vessels are spoken of in the parashah; and Rashba explains: it is written \"everything that comes into fire you shall pass through fire,\" etc. — whatever comes in fire must be made fit through fire; this is an eating vessel that absorbs, etc.; unlike here that does not absorb, like two pots, as written above siman 92 end of seif 8 and end of seif 93; and even though in Orach Chaim siman 491 seif 4 he requires libun — it is a mere stringency because sometimes dough spills on it:",
  "5#א": "Knife, etc. From what is written in the first chapter of Chullin (8b): for example, if he heated it in fire — and there is no question; and tevilah, as written in Avodah Zarah there: they heat and immerse, etc.; and as written: eating vessels, etc.; and this is not considered an eating vessel, for it still requires repair by cooking or roasting — \"not for a banquet\" does not apply. Mordechai there:",
  "5#ב": "Or, etc. For it is not specifically of slaughter, for it still requires great repair — flaying; and Rashi there (1a) s.v. and let it be derived, etc.; and the Gemara's language implies thus, for it says \"let it be derived\" — implying forbidden; and why did the Gemara not ask on permitted slaughter — one may say it holds like those who rinse, and even so forbidden l'chatchila as written there 107b, although the peel, etc.; and Rosh wrote l'chatchila forbidden relying that he will peel; and likewise — but this is a thing possible without rinsing, as written in siman 92 seif 2; therefore it only asked on flaying that is possible by roasting; and Tosafot there 33a s.v. and they are eaten — unlike on Shabbat because of blood on the mouth; and as written in siman 65 seif 5, and great rubbing is required on the mouth that is hard; and why it did not ask on Rava's words — because he did not mention l'chatchila in his words; and this is why Rashi did not explain the prohibition of the slaughterer per Rava — for if so let it ask on permitted, and Rosh's words there already rejected if Rashi meant forbidden and permitted l'chatchila:",
  "5#ג": "And some say. For he holds that matter in Chullin when they asked from a non-Jew and need not explain the Gemara there — it must be thus; for if in his sale or pledge it is nullified, as Tur wrote end of seif 139 in the name of R. Yonah and Ramban. And Mordechai holds like Tosafot in chapter 4 of Avodah Zarah 50b s.v. we require; but those brazier vessels, etc. — we establish like the rabbis, etc.; and the same applies, etc.; and Mordechai himself likewise there; but Ran wrote like R. Yitzchak and Ramban that only actual idolatry, as written there 53b, since their value is dear, etc.; unlike implements that are not as dear as actual idolatry; and as written in Tosefta chapter 7: even vessels a woman uses and priests stole and sold them — behold these are permitted; and likewise in the gloss in siman 146 seif 8; and his words here follow his view:",
  "5#ד": "The irons, etc. As above, that repair is still required; and he decided here they are not required because it is impossible to use them for another use, unlike a slaughter knife. Shach. And it is incorrect, for a slaughter knife too is not used, as written in Chullin there and Tosafot in chapter 157 of Shabbat 123b s.v. knife. And some say, etc.; and as written in Shulchan Aruch Orach Chaim siman 308. We do not follow here what is fit but the use; and see Chullin; rather it depends on the dispute mentioned and Issur VeHeter's words:",
  "5#ה": "But covering, etc. For the broth and steam rise to the cover and it is like a pot; and as written in chapter 25 (108:109) in \"he shook and covered\"; and likewise for impurity, as written in chapter 5 of Machshirin and chapter 2 there — unlike covering bread; and as written in chapter 2 there: he drank impure water, etc., entered water, etc., dried off, etc.:",
  "6#_": "Wooden vessel, etc. Even according to the rabbis in chapter 6 of Shabbat (60a) who say everything follows the stabilizer — here no tevilah is required, since one does not use them via metal, for we require eating vessels; and this is why he wrote \"outside,\" and as written above seif 1 regarding kunya — Tosafot s.v. and the halachah. And like kunya: although its essence is earthenware, we follow the coating; and even though for impurity, metal coating on plain wooden vessels we do not follow the coating and it is pure, as written at the end of Chagigah; and the other answer: the rabbis speak to R. Eliezer, etc.; meaning not only regarding the Temple table that Scripture calls wood and the altar, as Rashi wrote there — rather in all vessels, as written in chapter 11 of Kelim: a lampstand is impure and coated is pure; and there \"the rim,\" etc., and coated are pure; and Rosh strained there that it refers to impure iron — but it is not so, for it does not deal with this, for it says \"the rim,\" etc., of metal are impure — meaning they receive impurity; and likewise the rims before it; and this is what the mishnah in Chagigah means \"because they are coated\" — meaning R. Eliezer defiles because of the metal in them, and the rabbis purify because the metal is coating; and as written \"the rim,\" etc., and coated are pure; and likewise Rambam there and in his composition chapter 4 of Kelim — only his view is that even for a receiving vessel that receives impurity, the coating nullifies the vessel and it is pure; and the sugya does not imply thus, for it asks on the contrary, etc.; and even for the other answer there is no difficulty, only the coating is nullified to the vessel and as if not coated, and he retracted from what he wrote there \"let it be derived from coating,\" etc. — all this is the first answer; and in the Gemara there, and what he brought proof from Torat Kohanim \"every vessel,\" etc., \"I might add coating,\" etc. — it does not deal with metal, for only wood and leather are written there; and as written in chapter 97 of Kelim: this is the rule — all for coating are pure; and Raavad already challenged; nevertheless his words here are correct that coating is nullified to the vessel; and as written in chapter 11 of the five primary sources of impurity, halachah 11: their coatings are nullified to them; and here we follow the coating because use is in the coating inside:",
  "7#א": "Cup of, etc. Since one uses inside the silver — Semak and as above; and even though for kunya he ruled to immerse without a blessing, as written in seif 1 in the gloss — he wrote there because they are only for ornament; and he returned here and in seif 6 from what Beit Yosef ruled and adopted Tosafot's view and Beit HaGadol; and this is what he wrote in the gloss: and likewise a mill, even though in seif 1 he wrote \"some say,\" etc., and so is the practice:",
  "7#ב": "And likewise funnels, etc. Meaning: even though they do not receive, as written in chapter 11 of Kelim and chapter 1 of Shabbat and chapter 1 of Chullin (25a) and other places that plain metal vessels are impure:",
  "7#ג": "And only, etc. As written in chapter 13 of Kelim: wood serving metal is impure and metal serving wood is pure; and Mordechai in the name of Rambam: their law is like for impurity, as written in the first chapter of Shabbat (15b): glass vessels — why did they decree, etc. — evidently we compare to impurity; and the only difference is eating vessels follow place of use; and Rambam disagrees even in this; but for other tevilat kelim it equals impurity and purity; and this is why he wrote \"but a vessel,\" etc. — we establish like the rabbis who follow the stabilizer; and since the stabilizer is inside — and one may say regarding stabilizer in the first chapter of Shabbat (there) that the sages argue with R. Meir there that one does not stabilize for a vessel except for what is inside, as Tosafot wrote there; and even in this case Mordechai ruled there we follow the stabilizer like R. Meir, as we wrote; and these that are glued, etc.; and although everything follows the stabilizer, this applies where one used via the stabilizer, like a hole that was sealed, etc.; and there Rambam wrote: a pan that was pierced, etc., and his reason: for Rav Ashi in the first chapter of Shabbat (16b) who said: always for earthenware, etc. — the anonymous mishnah of these are chatzitzot comes according to R. Meir; and likewise Rambam in chapter 1 of the five primary sources of Kelim like Rav Ashi, and wrote they have no purification in a mikveh; and this is why he wrote \"and without sealing,\" etc.; but Rav Ashi's law itself requires study, for in Avodah Zarah he holds the reason when they break, etc.; and Tosafot wrote there; and it is difficult to distinguish between tevilah here and tevilah there. And were it not for their words, it would appear we certainly compare them to metal vessels and earthenware vessels; only R. Eliezer does not hold to compare one thing partly to earthenware and partly to metal except for impurity, since its beginning, etc.; but for tevilah, whether new or for purity, earthenware tevilah is not required — compare to metal vessels; and the mishnah mentioned comes according to the rabbis:",
  "8#א": "Or a renter. As written: only purchasers; and Rashi there s.v. purchasers and s.v. and as the incident, etc. — unlike renters, for they are not absolute, for \"purchasers\" is not written to include renters — rental for its day is sale, as written in chapter 4 of Bava Metzia (56b) — rather we learn from the incident that occurred:",
  "8#ב": "But, etc. Tosafot s.v. but, etc., that they did not say borrowers except because the non-Jew is still upon it and in his domain:",
  "8#ג": "And some, etc. So it appears from Tosafot's words already, etc., for there is no obligation on the second, for it is not purchased in his hand and not his; and this is why he wrote \"and likewise,\" etc.:",
  "9#א": "(Lekut) And if not, he immerses it. For we are stringent out of doubt. And Rambam ruled no tevilah is required, per his view that he wrote tevilat kelim is d'rabbanan and the verses are mere support (end of compilation):",
  "9#ב": "And if in the end, etc. Also depends on the doubt mentioned; and as written in Challah chapter 4: its stringency is found, etc.:",
  "10#א": "And some disagree. For he holds a craftsman acquires through enhancement of the vessel and it is his money; and like Rav Assi in chapter 9 of Bava Kamma (98b); but Rif ruled there like Rava, who concludes there (99b) that all, etc.; and likewise chapter 2 of Kiddushin; and Choshen Mishpat siman 306 seif 2; and Even HaEzer siman 28 seif 15 (and see our rabbi in Choshen Mishpat siman 306 s.k. 8, and from this is proof for Rif's words, etc.; but Rashba in Bava Kamma there rejected this — see there):",
  "10#ב": "And one should immerse it, etc. Even according to those who hold it is d'oraisa, the blessing is d'rabbanan and its doubt is lenient; and as written in Orach Chaim siman 436 — see there:",
  "10#ג": "And if part, etc. And so from Tosafot's words mentioned above, for he thought because a craftsman acquires through enhancement of the vessel he is liable:",
  "10#ד": "And likewise a craftsman, etc. Also depends on the dispute mentioned; but requires study, for even if he acquires he acquires only the enhancement; and Rashi in Bava Metzia 112a s.v. craftsman, etc.; and he wrote above \"and if part,\" etc.; and as Issur VeHeter wrote: whatever has part of the non-Jew in it has the law of the non-Jew's; and as written in seif 11 in the gloss: Jew and non-Jew, etc.; and if he bought it afterward he is liable; and likewise it is difficult from what he wrote \"or he gave part,\" etc.; and Peri Chadash likewise challenged:",
  "11#א": "Jew, etc. Tosafot s.v. if:",
  "11#ב": "But, etc. There we establish in chapter 2 of Pesachim (31b): a Jew from a non-Jew and a non-Jew from a Jew do not acquire a pledge; only a pledge from a non-Jew — even borrowers are thought liable, for \"purchasers\" is not written in Scripture except like the incident that occurred when they were decided for them; and the same applies to a pledge; but the non-Jew's must be absolute:",
  "11#ג": "Jew, etc. For he does not emerge from impurity through this tevilah, for the non-Jew is still upon it; and as written in the Yerushalmi that tevilah is that he emerge from the impurity of the non-Jew to the sanctity of Israel; and Ran:",
  "11#ד": "A Jew whom they stole, etc.; but, etc. For the owners' name already sank from him — unlike a thief or robber; and as written in chapter 7 of Kilayim: from when is it called, etc.; and in the Yerushalmi there R. Acha said: they sank and did not despair — its prohibition; R. Tarfon: they despaired and did not sink — its prohibition — d'rabbanan, meaning because of mar'it ha'ayin and not by law; and see above siman 296 seif 6:",
  "12#_": "Requires, etc. Chapter 10 of Mikvaot mishnah 5: all handles, etc.:",
  "13#א": "Must remove, etc. Mordechai there; and Rosh chapter 25 in the name of Sifri — it is not in our Sifri; and in Yalkut it exists: only the gold He said — only to remove their rust:",
  "13#ב": "If he is particular, etc. and if, etc. As written at the beginning of Eruvin (4b) and Sukkah and Yevamot and Niddah:",
  "14#א": "We do not believe, etc. For tevilat kelim is d'oraisa, as written in the Gemara there, and so most poskim; and a minor regarding what is not in his hand is not believed even for d'rabbanan, as written in chapter 2 of Ketubot; and these are believed, etc., but not young minors; and likewise chapter 5 of Eruvin (58b): even a slave, etc., but not a minor; but regarding what is in his hand he is believed for d'rabbanan, as written in the first chapter of Pesachim (4b): they trusted him, etc.; and it implies specifically for d'rabbanan, although slave and maidservant are believed even for d'oraisa; and there it does not say specifically d'rabbanan, only because there is trouble, as Yerushalmi writes — this refers only to men and slaves; and Yerushalmi there: some do not teach women because they are lazy and they check — all the more so minors, because they are not believed for d'oraisa; and so Tosafot there; and Tosafot in Eruvin 31b s.v. here. Therefore it appears to explain, etc. (and see end of siman 127):",
  "14#ב": "But, etc. As written there: standing and seeing him, and intent for tevilah is not required; even if they fell by themselves into water it suffices; and as written in chapter 2 of Chullin (31); and Rav — Rav Nachman holds like him there and in chapter 2 of Chagigah; and as the poskim wrote; and even if it fell from a bridge, as we wrote for R. Natan that we establish like him; and intent is not required:",
  "15#א": "If he immersed, etc. As above in the preceding seif; and in Even HaEzer; and as Beit HaGadol wrote, unlike Shach (and Maharshal is not necessary, as the later authorities wrote):",
  "15#ב": "But he is not, etc. As written above siman 118: he is not believed neither to be lenient nor stringent:",
  "16#_": "And if he transgressed, etc. Tosafot there s.v. and all of them, etc.; and even for the view they wrote \"however,\" etc. — that is for those who hold ntiluf is forbidden; and so in the Gemara there it says: one taught, etc., and it answers nothing on tevilah; and one must say either the first view that it teaches and only asks about hag'alah and libun, or the latter view; and even though in Rosh there at the beginning of his words it appears the latter baraita refers only to hag'alah and libun — the Gemara's plain meaning does not imply thus, and he only wrote for clarity:",
};

fs.writeFileSync(path.join(dir, 'siftei-kohen.json'), JSON.stringify(sifteiKohen, null, 2) + '\n');
fs.writeFileSync(path.join(dir, 'beur-hagra.json'), JSON.stringify(beurHagra, null, 2) + '\n');
